/// Implemented on iOS only. The generated Kotlin interface is never registered.
///
/// Generated protocol from Pigeon that represents a handler of messages from Flutter.
protocol NfcIosHostApi {
  func tagSessionReadingAvailable() throws -> Bool
  /// `NFCTag.isAvailable` for the tag behind [handle].
  ///
  /// Asks whether *this* tag is still connected and reachable, not whether some tag is in
  /// the field. False for a handle the session has already let go of.
  func tagIsAvailable(handle: String) throws -> Bool
  func tagSessionSetAlertMessage(alertMessage: String, completion: @escaping (Result<Void, Error>) -> Void)
  /// Drops the current tag and polls again, without tearing down the reader sheet.
  func tagSessionRestartPolling(completion: @escaping (Result<Void, Error>) -> Void)
  func vasSessionReadingAvailable() throws -> Bool
  func vasSessionBegin(configurations: [VasCommandConfigurationPigeon], alertMessage: String?, completion: @escaping (Result<Void, Error>) -> Void)
  func vasSessionInvalidate(alertMessage: String?, errorMessage: String?, completion: @escaping (Result<Void, Error>) -> Void)
  func vasSessionSetAlertMessage(alertMessage: String, completion: @escaping (Result<Void, Error>) -> Void)
  /// The live status, as opposed to the copy captured at discovery.
  func ndefQueryStatus(handle: String, completion: @escaping (Result<QueryNdefStatusResponsePigeon, Error>) -> Void)
  /// An NDEF message delivered by iOS background tag reading. Consumed by the first call.
  func takeInitialNdefMessage() throws -> NdefMessagePigeon?
